package io.knowledgebrain.notification;
import java.util.*;import java.net.*;import java.net.http.*;import java.time.Duration;import tools.jackson.databind.json.JsonMapper;
final class DispatchSnapshot {
 record Item(UUID deliveryId,String envelope){}record Page(List<Item> items,String nextAfter){}
 private final URI origin;private final HttpClient http;private final String key;private final JsonMapper json=JsonMapper.builder().build();
 DispatchSnapshot(String origin,String trust,String key)throws Exception{this.origin=NotificationHttp.origin(origin);http=NotificationHttp.client(trust);if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Dedicated dispatch snapshot key required");this.key=key;}
 void backfill(NotificationStore store){String after=null;do{var r=NotificationHttp.send(http,HttpRequest.newBuilder(origin.resolve("/internal/planning/dispatched-reminders?limit=50"+(after==null?"":"&after="+after))).header("Authorization","Bearer "+key).timeout(Duration.ofSeconds(8)).GET().build(),4194304);if(r.statusCode()!=200)throw new IllegalStateException("Canonical dispatch recovery unavailable");var p=json.readValue(r.body(),Page.class);if(p==null||p.items()==null||p.items().size()>50)throw DispatchEvent.bad();String last=after;for(var item:p.items()){if(item.deliveryId()==null||last!=null&&item.deliveryId().toString().compareTo(last)<=0||item.envelope()==null||item.envelope().length()>90000)throw DispatchEvent.bad();var bytes=Base64.getDecoder().decode(item.envelope());var event=DispatchEvent.decode(bytes);if(event.source()==null||!event.source().deliveryId().equals(item.deliveryId()))throw DispatchEvent.bad();store.accept(bytes);last=item.deliveryId().toString();}if(p.nextAfter()!=null&&(p.items().size()!=50||!p.nextAfter().equals(last)))throw DispatchEvent.bad();after=p.nextAfter();}while(after!=null);store.seededNow();}
}
